#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1000;
int dist[MAXN + 1][MAXN + 1];

void precompute() {
    for (int i = 0; i <= MAXN; i++)
        for (int j = 0; j <= MAXN; j++)
            dist[i][j] = 1e9;

    queue<pair<int,int>> q;
    dist[1][0] = 0;
    dist[1][1] = 0;
    q.push({1, 0});
    q.push({1, 1});

    while (!q.empty()) {
        auto [a, b] = q.front(); q.pop();
        int d = dist[a][b];
        int nexts[] = {a + b, abs(a - b)};
        for (int nx : nexts) {
            if (nx <= MAXN && nx > 0 && dist[max(a, nx)][min(a, nx)] > d + 1) {
                dist[max(a, nx)][min(a, nx)] = d + 1;
                q.push({max(a, nx), min(a, nx)});
            }
        }
    }
}

