#include <bits/stdc++.h>
using namespace std;

/*
We need the minimum number of multiplications/divisions to obtain x^n from x.

Represent every available value as x^k. Starting from exponent 1.
One operation combines two already available exponents a,b into a+b
(multiplication) or |a-b| (division, assuming positive exponent result).

Thus we need the shortest "addition-subtraction chain" for n starting from 1.

For the UVa-style constraints of this classic problem, n <= 1000.
We can solve each n with IDDFS/backtracking.

State:
  chain[0..d], chain[0] = 1, chain[i] are exponents obtained so far,
  with chain[d] being the most recently obtained exponent.
At each step we generate a new exponent from chain[d] and any previous chain[i]
using + or absolute difference. This is sufficient for optimal search.

Pruning:
- If current maximum m = chain[d], then in remaining r steps the largest
  reachable exponent is at most m * 2^r. If that's still < target, prune.
- Avoid generating non-positive or too-large values.
- Try larger candidates first to reach target quickly.

This is the standard solution for "Power Calculus".
*/

static int target;
static int chainv[64];
static bool used[10005];

bool dfs(int depth, int maxDepth) {
    if (chainv[depth] == target) return true;
    if (depth == maxDepth) return false;

    int cur = chainv[depth];
    int remain = maxDepth - depth;

    // Upper-bound pruning: even doubling every remaining step can't reach target.
    long long mx = cur;
    for (int i = 0; i < remain; ++i) mx <<= 1;
    if (mx < target) return false;

    vector<int> cand;
    cand.reserve((depth + 1) * 2);

    memset(used, 0, sizeof(used));

    for (int i = depth; i >= 0; --i) {
        int a = chainv[i];

        int s = cur + a;
        if (s > 0 && s <= 2 * target && !used[s]) {
            used[s] = true;
            cand.push_back(s);
        }

        int d = abs(cur - a);
        if (d > 0 && d <= 2 * target && !used[d]) {
            used[d] = true;
            cand.push_back(d);
        }
    }

    sort(cand.begin(), cand.end(), greater<int>());

    for (int v : cand) {
        chainv[depth + 1] = v;
        if (dfs(depth + 1, maxDepth)) return true;
    }
    return false;
}

int solve(int n) {
    if (n == 1) return 0;
    target = n;
    chainv[0] = 1;
    for (int lim = 1; ; ++lim) {
        if (dfs(0, lim)) return lim;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    while (cin >> n && n) {
        cout << solve(n) << '\n';
    }
    return 0;
}

