#include <stdio.h>
#include <string.h>

#define MAXN 10000
#define INF 1000000000

/*
  We need the minimum number of multiplications/divisions to obtain x^n from x,
  where every intermediate value must be x^k for some positive integer k.

  This is exactly the shortest addition-subtraction chain length for n, starting
  from exponent 1. From known results, for n <= 10000 the optimal length is at
  most 14, so IDDFS works well.

  We maintain a chain a[0..d], with a[0] = 1 and each next exponent formed as:
      a[d+1] = a[i] + a[j]  or  |a[i] - a[j]|
  using previous exponents, and must stay positive.

  Pruning:
  - Keep chain strictly increasing by only appending values > current maximum.
    Any optimal chain can be rearranged this way.
  - If even repeated doubling for remaining steps cannot reach n, prune.
*/

static int target;
static int chain[32];

static int dfs(int depth, int maxDepth) {
    if (chain[depth] == target) return 1;
    if (depth == maxDepth) return 0;

    /* Upper-bound reachability by doubling */
    int mx = chain[depth];
    for (int i = depth; i < maxDepth; i++) {
        if (mx >= target) break;
        mx <<= 1;
    }
    if (mx < target) return 0;

    int used[MAXN + 1];
    memset(used, 0, sizeof(used));

    int curMax = chain[depth];

    /* Try larger candidates first */
    for (int i = depth; i >= 0; i--) {
        for (int j = i; j >= 0; j--) {
            int v1 = chain[i] + chain[j];
            if (v1 > curMax && v1 <= MAXN && !used[v1]) {
                used[v1] = 1;
                chain[depth + 1] = v1;
                if (dfs(depth + 1, maxDepth)) return 1;
            }

            int v2 = chain[i] - chain[j];
            if (v2 < 0) v2 = -v2;
            if (v2 > curMax && v2 <= MAXN && !used[v2]) {
                used[v2] = 1;
                chain[depth + 1] = v2;
                if (dfs(depth + 1, maxDepth)) return 1;
            }
        }
    }

    return 0;
}

int main(void) {
    int n;
    while (scanf("%d", &n) == 1 && n) {
        if (n == 1) {
            printf("0\n");
            continue;
        }

        target = n;
        chain[0] = 1;

        int ans = 0;
        while (!dfs(0, ans)) ans++;
        printf("%d\n", ans);
    }
    return 0;
}

