    public static void main(String[] args) {
        Arrays.fill(best, Integer.MAX_VALUE);
        best[1] = 0;

        // Use DFS with pruning to compute minimal operations up to 2*MAX
        dfs(1, 0, 1);

        Scanner sc = new Scanner(System.in);
        while (sc.hasNextInt()) {
            int n = sc.nextInt();
            if (n == 0) break;
            System.out.println(best[n]);
        }
    }

    static void dfs(int current, int depth, int maxReach) {
        if (depth > 12 || current > MAX * 2 || current <= 0) return;
        if (depth >= best[current]) return;
        best[current] = depth;

        // Try all possible previous values to generate new ones
        int limit = maxReach;
        for (int i = 1; i <= limit; i++) {
            if (best[i] == Integer.MAX_VALUE) continue;
            // addition
            int next = current + i;
            if (next > 0 && next < MAX * 2) {
                dfs(next, depth + 1, Math.max(maxReach, next));
            }
            // subtraction (if result is positive)
            if (current > i) {
                next = current - i;
                dfs(next, depth + 1, maxReach);
            }
        }
    }
}

