    static boolean dfs(int depth, int maxDepth, int target) {
        int last = chain[depth - 1];
        if (last == target) return true;
        if (depth > maxDepth) return false;

        // Pruning: even doubling at every step can't reach target
        if (last << (maxDepth - depth + 1) < target) return false;

        for (int i = depth - 1; i >= 0; i--) {
            // Try addition
            int next = last + chain[i];
            if (next > 0) {
                chain[depth] = next;
                if (dfs(depth + 1, maxDepth, target)) return true;
            }
            // Try subtraction (last - chain[i])
            if (i != depth - 1) { // avoid 0
                int next2 = last - chain[i];
                if (next2 > 0) {
                    chain[depth] = next2;
                    if (dfs(depth + 1, maxDepth, target)) return true;
                }
            }
        }
        return false;
    }
}

