import java.util.*;

public class Main {
    static final int MAX_N = 1000; // safely covers typical UVa 137 / POJ style limits
    static int[] best = new int[MAX_N + 1];

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<Integer> queries = new ArrayList<>();
        int maxQuery = 0;

        while (true) {
            String line = br.readLine();
            if (line == null) break;
            line = line.trim();
            if (line.isEmpty()) continue;
            int n = Integer.parseInt(line);
            if (n == 0) break;
            queries.add(n);
            maxQuery = Math.max(maxQuery, n);
        }

        if (queries.isEmpty()) return;

        int limit = Math.max(MAX_N, maxQuery);

        best = new int[limit + 1];
        Arrays.fill(best, Integer.MAX_VALUE);
        best[1] = 0;

        // Iterative deepening DFS over addition-subtraction chains.
        for (int depth = 0; ; depth++) {
            int[] chain = new int[depth + 1];
            chain[0] = 1;
            dfs(0, depth, chain, limit);

            boolean done = true;
            for (int n : queries) {
                if (best[n] == Integer.MAX_VALUE) {
                    done = false;
                    break;
                }
            }
            if (done) break;
        }

        StringBuilder sb = new StringBuilder();
        for (int n : queries) {
            sb.append(best[n]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static void dfs(int d, int maxDepth, int[] chain, int limit) {
        int current = chain[d];
        if (best[current] > d) best[current] = d;
        if (d == maxDepth) return;

        // Prune: even repeated doubling cannot improve enough to reach new values meaningfully.
        long maxReach = current;
        for (int i = d; i < maxDepth; i++) maxReach <<= 1;
        if (maxReach < 1) return;

        // Generate next exponents using addition/subtraction chains:
        // next = chain[d] +/- chain[i], must be positive and larger than current.
        boolean[] used = new boolean[Math.min(limit + 1, (int)Math.min(Integer.MAX_VALUE, maxReach) + 1)];
        for (int i = d; i >= 0; i--) {
            int a = chain[i];

            int add = current + a;
            if (add <= limit && add > current && !used[add]) {
                used[add] = true;
                chain[d + 1] = add;
                if (canStillReach(add, maxDepth - (d + 1), limit)) {
                    dfs(d + 1, maxDepth, chain, limit);
                }
            }

            int sub = current - a;
            if (sub > current) continue;
            if (sub > 0 && sub <= limit && sub > current && !used[sub]) {
                used[sub] = true;
                chain[d + 1] = sub;
                if (canStillReach(sub, maxDepth - (d + 1), limit)) {
                    dfs(d + 1, maxDepth, chain, limit);
                }
            }
        }

        // Also allow combinations of any two previous chain values.
        for (int i = d; i >= 0; i--) {
            for (int j = i; j >= 0; j--) {
                int v1 = chain[i], v2 = chain[j];

                int add = v1 + v2;
                if (add <= limit && add > current && !used[add]) {
                    used[add] = true;
                    chain[d + 1] = add;
                    if (canStillReach(add, maxDepth - (d + 1), limit)) {
                        dfs(d + 1, maxDepth, chain, limit);
                    }
                }

                int sub = Math.abs(v1 - v2);
                if (sub <= limit && sub > current && !used[sub]) {
                    used[sub] = true;
                    chain[d + 1] = sub;
                    if (canStillReach(sub, maxDepth - (d + 1), limit)) {
                        dfs(d + 1, maxDepth, chain, limit);
                    }
                }
            }
        }
    }

    static boolean canStillReach(int value, int stepsLeft, int limit) {
        long reach = value;
        for (int i = 0; i < stepsLeft; i++) reach <<= 1;
        return reach >= value && value <= limit;
    }
}

