    # IDDFS for addition-subtraction chain
    def dfs(chain, target, depth):
        current = chain[-1]
        if current == target:
            return True
        if depth == 0:
            return False
        # Pruning: even if we double every step, can we reach target?
        if current * (2 ** depth) < target:
            return False

        # Try all pairs from chain
        for i in range(len(chain)-1, -1, -1):
            for j in range(i, -1, -1):
                # addition
                val = chain[i] + chain[j]
                if val > 0 and val <= target * 2:  # rough bound
                    chain.append(val)
                    if dfs(chain, target, depth - 1):
                        return True
                    chain.pop()
